const fs = require('node:fs');
const path = require('node:path');
const {
  createRunOncePlugin,
  withAppBuildGradle,
  withDangerousMod,
  withGradleProperties,
} = require('expo/config-plugins');

// Turns on R8 for the Android `release` build type.
//
// Google Play's App optimisation report scored Boardsesh at Obfuscation 1%
// (threshold 25%) because minifyEnabled has never been anything but false: the
// Expo prebuild template defaults it off, android/ is regenerated by
// `expo prebuild --clean` on every CI run, and nothing in this repo set the
// property. Every release APK and Play AAB shipped with fully readable
// Java/Kotlin class, method and field names.
//
// Hand-rolled rather than expo-build-properties on purpose: this plugin THROWS
// when the generated build.gradle stops reading our property (see
// assertTemplateReadsMinifyProperty). expo-build-properties cannot — it would
// silently write a key nobody reads and drop us back to 1% with a green build.
const MINIFY_PROPERTY = 'android.enableMinifyInReleaseBuilds';

// Resource shrinking is a SEPARATE axis from obfuscation: it contributes nothing
// to the Play metric this plugin exists to fix, and it fails silently (drawables
// reached by name through Resources.getIdentifier / resolveAssetSource are
// stripped, and you find out on a device). Deliberately off; flip this constant
// and the property is written the same way the minify one is.
const ENABLE_SHRINK_RESOURCES = false;
const SHRINK_RESOURCES_PROPERTY = 'android.enableShrinkResourcesInReleaseBuilds';

// AGP's stock rule file. The `-optimize` variant is the same file WITHOUT
// `-dontoptimize`, so R8 additionally inlines, merges classes and devirtualises.
// That is the deliberate choice here (it also lifts Play's Optimisation
// category), and it is the one dial to turn back if a release-only crash shows
// up near a JNI or Expo-module boundary: swapping this to 'proguard-android.txt'
// keeps every rename — and so keeps the obfuscation fix — while dropping the
// optimisation pass.
const PROGUARD_BASE_FILE = 'proguard-android-optimize.txt';

// The two shapes the generated build.gradle must still have for MINIFY_PROPERTY
// to do anything. SDK 56 called this `android.enableProguardInReleaseBuilds`; if
// a future SDK renames it again, writing our property becomes a silent no-op and
// the app ships UNOBFUSCATED. Fail prebuild instead of shipping that.
const MINIFY_PROPERTY_READ = /findProperty\(\s*['"]android\.enableMinifyInReleaseBuilds['"]\s*\)/;
// The lazy `buildTypes { ... release {` prefix is the same anchoring trick
// applyAndroidReleaseSigning uses: `debug {` is textually first inside
// buildTypes, so a `minifyEnabled` that appears ONLY in the debug block cannot
// satisfy this.
const MINIFY_APPLIED_IN_RELEASE =
  /buildTypes\s*\{[\s\S]*?\brelease\s*\{[\s\S]*?\bminifyEnabled\s+enableMinifyInReleaseBuilds\b/;
const PROGUARD_BASE_LINE = /getDefaultProguardFile\(\s*(["'])proguard-android\.txt\1\s*\)/;

// Marker so the proguard-rules.pro append is idempotent across repeated
// prebuilds and greppable in CI logs.
const KEEP_RULES_MARKER = 'boardsesh-android-minify';

// Every -keep LOWERS the obfuscation percentage this plugin exists to raise, so
// each rule below names the exact call site that forces it. Anything already
// covered by an AAR consumer rule or by AGP's stock file is deliberately ABSENT:
// all five local Expo modules (expo-modules-core keeps
// `* extends expo.modules.kotlin.modules.Module` with allowobfuscation — they
// ARE renamed, and Expo resolves them by the Name() string in the DSL), every
// class declaring a native/external method (AGP's
// `-keepclasseswithmembernames class * { native <methods>; }` covers worklets,
// Nitro and MMKV), the manifest-declared BoardSessionService /
// BoardSessionActionReceiver / MainActivity (aapt2 generates keeps for those),
// and the whole BLE stack (the only reflection in react-native-ble-plx targets
// the platform class android.bluetooth.BluetoothGatt, which R8 never touches).
const KEEP_RULES = `
# --- ${KEEP_RULES_MARKER} ---------------------------------------------------
# Injected by packages/mobile/plugins/with-android-minify.js on every prebuild.
# android/ is generated, so none of this can be committed.

# Line numbers survive R8 so a retraced Play / Sentry stack trace still points at
# a line. Under -optimize, inlining collapses frames, which makes this
# load-bearing rather than nice-to-have. These are attributes, not names: zero
# effect on the obfuscation percentage.
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile

# expo.modules.ExpoModulesPackageList is GENERATED into the app module by the
# expo-autolinking Gradle plugin and reached ONLY reflectively, from three sites:
#   expo/android/.../ExpoModulesPackage.kt          Class.forName(...).getMethod("getPackageList")
#   expo-modules-core/.../ExpoModulesHelper.kt      Class.forName(...).getConstructor().newInstance()
#   expo-modules-core/.../TaskServiceProviderHelper.kt
# Nothing references it statically, so R8 is free to rename it. Expo's own
# consumer rule is -keepclassmembers, which pins MEMBERS of a class that survives
# on its own; it does NOT pin the class name. All three call sites SWALLOW the
# failure and log "Couldn't get expo package list", so the app boots with ZERO
# Expo modules (no expo-constants, no expo-updates, no expo-sqlite, no
# board-renderer) instead of crashing. One class name; the failure is total and
# silent, which is why it is first.
-keep class expo.modules.ExpoModulesPackageList { *; }

# libboard_renderer_jni.so exports
#   Java_com_boardsesh_boardrenderer_BoardRendererBridge_nativeRender
# (modules/board-renderer/android/src/main/cpp/jni_bridge.cpp), so this class's
# fully-qualified name and that method name are a native ABI contract: rename
# either and the first board render is an UnsatisfiedLinkError. AGP's stock file
# already ships the identical rule with \`class *\`; narrowing it to our class
# makes the contract explicit in our own source and keeps it if that default
# ever changes. Names only -- R8 may still shrink the class.
-keepclasseswithmembernames class com.boardsesh.boardrenderer.BoardRendererBridge {
    native <methods>;
}

# @sentry/react-native compares these two react-native-screens class names as
# STRINGS to decide when a navigation has drawn --
# RNSentryReactFragmentLifecycleTracer.java, both
# \`"...".equals(f.getClass().getCanonicalName())\`. react-native-screens ships no
# consumer rules, so R8 renames both and Sentry's time-to-initial-display
# instrumentation silently stops emitting; we run tracesSampleRate 0.1, so that
# is live telemetry. -keepnames, not -keep: the classes may still be shrunk, only
# the names are pinned.
-keepnames class com.swmansion.rnscreens.ScreenStackFragment
-keepnames class com.swmansion.rnscreens.events.ScreenAppearEvent
# --- end ${KEEP_RULES_MARKER} -----------------------------------------------
`;

/**
 * Upserts the R8 gradle properties into the parsed gradle.properties. Pure
 * transform for testability, mirroring applyGradleMemory in
 * with-android-gradle-memory.js (the repo's other withGradleProperties writer).
 *
 * @param {Array<{type: string, key?: string, value?: string}>} gradleProps
 * @returns {Array<{type: string, key?: string, value?: string}>}
 */
function applyMinifyProperties(gradleProps) {
  const properties = { [MINIFY_PROPERTY]: 'true' };
  if (ENABLE_SHRINK_RESOURCES) {
    properties[SHRINK_RESOURCES_PROPERTY] = 'true';
  }

  for (const [key, value] of Object.entries(properties)) {
    const existing = gradleProps.find((entry) => entry.type === 'property' && entry.key === key);
    if (existing) {
      existing.value = value;
    } else {
      gradleProps.push({ type: 'property', key, value });
    }
  }
  return gradleProps;
}

/**
 * Read-only assertion over the generated android/app/build.gradle: the property
 * we write is only meaningful because the template reads it AND wires it to the
 * release build type. Returns `contents` unchanged so the caller never mutates.
 *
 * @param {string} contents - the build.gradle source
 * @returns {string} the same source
 */
function assertTemplateReadsMinifyProperty(contents) {
  if (!MINIFY_PROPERTY_READ.test(contents)) {
    throw new Error(
      `with-android-minify: the generated build.gradle no longer reads \`${MINIFY_PROPERTY}\`. ` +
        'The Expo template renamed the minification flag (SDK 56 called it ' +
        'android.enableProguardInReleaseBuilds). Setting our gradle property is now a silent ' +
        'no-op and the release build would ship UNOBFUSCATED — Google Play scores that at 1%. ' +
        'Find the new property name in the template and update MINIFY_PROPERTY.',
    );
  }

  if (!MINIFY_APPLIED_IN_RELEASE.test(contents)) {
    throw new Error(
      'with-android-minify: the `release` build type no longer applies ' +
        '`minifyEnabled enableMinifyInReleaseBuilds`. The property is still read but is no longer ' +
        'wired to the release build type, so minification would silently not run and the release ' +
        'build would ship UNOBFUSCATED.',
    );
  }

  return contents;
}

/**
 * Swaps AGP's stock ProGuard file for the `-optimize` variant. Pure string
 * transform for testability; idempotent.
 *
 * @param {string} contents - the build.gradle source
 * @returns {string} the rewritten source
 */
function applyProguardBaseFile(contents) {
  if (contents.includes(PROGUARD_BASE_FILE)) {
    return contents;
  }

  const rewritten = contents.replace(PROGUARD_BASE_LINE, `getDefaultProguardFile("${PROGUARD_BASE_FILE}")`);
  if (rewritten === contents) {
    throw new Error(
      'with-android-minify: could not find `getDefaultProguardFile("proguard-android.txt")` in ' +
        `build.gradle, so the ${PROGUARD_BASE_FILE} swap did not apply. The Expo template changed ` +
        'its proguardFiles line; update PROGUARD_BASE_LINE to match.',
    );
  }
  return rewritten;
}

/**
 * Appends the keep rules to the template's android/app/proguard-rules.pro. Pure
 * string transform for testability; idempotent via KEEP_RULES_MARKER.
 *
 * @param {string} contents - the proguard-rules.pro source
 * @returns {string} the rewritten source
 */
function applyKeepRules(contents) {
  if (contents.includes(KEEP_RULES_MARKER)) {
    return contents;
  }
  return `${contents.trimEnd()}\n${KEEP_RULES}`;
}

function withAndroidMinify(config) {
  let modConfigWithProperties = withGradleProperties(config, (modConfig) => {
    modConfig.modResults = applyMinifyProperties(modConfig.modResults);
    return modConfig;
  });

  modConfigWithProperties = withAppBuildGradle(modConfigWithProperties, (modConfig) => {
    assertTemplateReadsMinifyProperty(modConfig.modResults.contents);
    modConfig.modResults.contents = applyProguardBaseFile(modConfig.modResults.contents);
    return modConfig;
  });

  return withDangerousMod(modConfigWithProperties, [
    'android',
    (modConfig) => {
      const rulesPath = path.join(modConfig.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
      const contents = fs.readFileSync(rulesPath, 'utf8');
      fs.writeFileSync(rulesPath, applyKeepRules(contents));
      return modConfig;
    },
  ]);
}

module.exports = createRunOncePlugin(withAndroidMinify, 'with-android-minify', '1.0.0');
module.exports.applyMinifyProperties = applyMinifyProperties;
module.exports.assertTemplateReadsMinifyProperty = assertTemplateReadsMinifyProperty;
module.exports.applyProguardBaseFile = applyProguardBaseFile;
module.exports.applyKeepRules = applyKeepRules;
module.exports.MINIFY_PROPERTY = MINIFY_PROPERTY;
module.exports.SHRINK_RESOURCES_PROPERTY = SHRINK_RESOURCES_PROPERTY;
module.exports.ENABLE_SHRINK_RESOURCES = ENABLE_SHRINK_RESOURCES;
module.exports.PROGUARD_BASE_FILE = PROGUARD_BASE_FILE;
module.exports.KEEP_RULES_MARKER = KEEP_RULES_MARKER;
module.exports.KEEP_RULES = KEEP_RULES;
